pub open spec fn vrs_controller_model() -> ControllerModel {
    ControllerModel {
        reconcile_model: Cluster::installed_reconcile_model::<VReplicaSetReconciler, VReplicaSetReconcileState, VReplicaSetView, VoidEReqView, VoidERespView>(),
        external_model: None,
    }
}

// File: controllers/vreplicaset_controller/trusted/rely_guarantee.rs
pub open spec fn vrs_guarantee_create_req(req: CreateRequest) -> StatePred<ClusterState> {
    |s: ClusterState| {
        let owner_references = req.obj.metadata.owner_references->0;
        &&& req.obj.kind == Kind::PodKind
        &&& req.obj.metadata.owner_references is Some
        &&& exists |vrs: VReplicaSetView| 
            owner_references == seq![#[trigger] vrs.controller_owner_ref()]
    }
}

pub open spec fn vrs_guarantee_get_then_delete_req(req: GetThenDeleteRequest) -> StatePred<ClusterState> {
    |s: ClusterState| {
        &&& req.key.kind == Kind::PodKind
        &&& exists |vrs: VReplicaSetView| 
            req.owner_ref == #[trigger] vrs.controller_owner_ref()
    }
}

pub open spec fn vrs_guarantee(controller_id: int) -> StatePred<ClusterState> {
    |s: ClusterState| {
        forall |msg| {
            &&& #[trigger] s.in_flight().contains(msg)
            &&& msg.content is APIRequest
            &&& msg.src.is_controller_id(controller_id)
        } ==> match msg.content->APIRequest_0 {
            APIRequest::ListRequest(_) => true,
            APIRequest::CreateRequest(req) => vrs_guarantee_create_req(req)(s),
            APIRequest::GetThenDeleteRequest(req) => vrs_guarantee_get_then_delete_req(req)(s),
            _ => false, // vrs doesn't send other requests (yet).
        }
    }
}



// File: controllers/vreplicaset_controller/proof/guarantee.rs
#[verifier(rlimit(100))]
pub proof fn guarantee_condition_holds(spec: TempPred<ClusterState>, cluster: Cluster, controller_id: int)
    requires
        spec.entails(lift_state(cluster.init())),
        // The cluster always takes an action (without weak fairness).
        spec.entails(always(lift_action(cluster.next()))),
        // The vrs type is installed in the cluster.
        cluster.type_is_installed_in_cluster::<VReplicaSetView>(),
        // The vrs controller runs in the cluster.
        cluster.controller_models.contains_pair(controller_id, vrs_controller_model()),
    ensures
        spec.entails(always(lift_state(vrs_guarantee(controller_id))))
